package com.order.order_service.client;
import com.order.order_service.dto.DeliveryRequest; import java.util.Map; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.PostMapping; import org.springframework.web.bind.annotation.RequestBody; import org.springframework.web.bind.annotation.RequestHeader;
@FeignClient(name="delivery-service",url="${delivery-service.url:http://localhost:8087}") public interface DeliveryClient { @PostMapping("/internal/deliveries") Object create(@RequestHeader("X-Internal-Key") String key,@RequestBody DeliveryRequest request); @GetMapping("/orders/{id}/driver-location") Map<String,Object> location(@PathVariable("id") long id,@RequestHeader("Authorization") String authorization); }
